<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Http\Requests\ProductRequest;use App\Models\Product;class AdminProductController extends Controller{public function index(){return response()->json(Product::with('category:id,name')->latest()->paginate(12));}public function store(ProductRequest $r){return response()->json(['data'=>Product::create($r->validated())],201);}public function show(Product $product){return ['data'=>$product->load('category')];}public function update(ProductRequest $r,Product $product){$product->update($r->validated());return ['data'=>$product->fresh('category')];}public function destroy(Product $product){if($product->purchaseItems()->exists()){$product->update(['is_active'=>false]);return ['message'=>'Produit désactivé pour préserver l’historique.'];}$product->delete();return response()->noContent();}}
